sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var pref = api.data.get_user_preference_1.output.data.GlideDomain_Query.user.preferences[0].value;
    var parFilters = JSON.parse(pref);
    var queries = [];
    var final_query = '';
    for(var i=0;i<parFilters.length;i++){
			var t = parFilters[i].apply_to[0].split('.')[1];
			if(parFilters[i].label == 'Portfolio'|| parFilters[i].label == 'Program' || parFilters[i].label == 'Project Manager')
				queries.push(t+'.sys_idIN'+parFilters[i].values);
			else
				queries.push(t+'IN'+parFilters[i].values);
		}
		final_query = queries.join("^");
		api.setState("filter", final_query);
        api.setState("parFilters",parFilters);
}
